INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist DHCP für die automatische Adresszuweisung in IPv4-Netzen zuständig?', 2, '[{"text": "Ja", "correct": true, "because": "Dynamisches Host-Konfigurationsprotokoll"}, {"text": "Nein", "correct": false, "because": "Korrekte Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe hat DHCP in einem Netzwerk?', 3, '[{"text": "IP-Adressen automatisch vergeben", "correct": true, "because": "Hauptfunktion von DHCP"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Nicht DHCP-Aufgabe"}, {"text": "Netzwerkgeschwindigkeit erhöhen", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) DHCP verwendet IPv4-Adressen. b) Es funktioniert nur mit statischen IPs.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist für dynamische IPs"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei den DHCP-Grundlagen?', 4, '[{"text": "IP-Pool", "correct": false, "because": "Definiert verfügbare Adressen"}, {"text": "Lease-Zeit", "correct": false, "because": "Bestimmt Gültigkeit"}, {"text": "Farbschema", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob DHCP die manuelle Konfiguration ersetzt?', 2, '[{"text": "Ja", "correct": true, "because": "Automatisiert Adressvergabe"}, {"text": "Nein", "correct": false, "because": "Alternative zur Manual"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Adresse vergibt DHCP nicht?', 3, '[{"text": "Netzwerkadresse", "correct": true, "because": "Reserviert für Netz"}, {"text": "Erste nutzbare Adresse", "correct": false, "because": "Kann vergeben werden"}, {"text": "Letzte nutzbare Adresse", "correct": false, "because": "Kann vergeben werden"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten gehören zu DHCP?', 5, '[{"text": "Server", "correct": true, "because": "Vergibt Adressen"}, {"text": "Client", "correct": true, "because": "Fordert Adressen an"}, {"text": "Router", "correct": false, "because": "Nur optional"}, {"text": "Firewall", "correct": false, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) DHCP reduziert IP-Konflikte. b) Es funktioniert nur mit IPv6. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) auch IPv4"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für DHCP?', 4, '[{"text": "IP-Pool", "correct": false, "because": "Definiert Adressbereich"}, {"text": "Server", "correct": false, "because": "Vergibt Adressen"}, {"text": "Betriebssystem", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Nutzt DHCP einen IP-Bereich?', 2, '[{"text": "Ja", "correct": true, "because": "Pool für Vergabe"}, {"text": "Nein", "correct": false, "because": "Korrekte Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Adresse könnte DHCP aus 192.168.1.0/24 vergeben?', 4, '[{"text": "192.168.1.100", "correct": true, "because": "Nutzbarer Bereich"}, {"text": "192.168.1.0", "correct": false, "because": "Netzwerkadresse"}, {"text": "192.168.1.255", "correct": false, "because": "Broadcast"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass DHCP keine Lease-Zeit hat. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Lease-Zeit ist essenziell"}, {"text": "Ja", "correct": false, "because": "Falsches Verständnis"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei DHCP?', 3, '[{"text": "IP-Pool", "correct": true, "because": "Definiert verfügbare Adressen"}, {"text": "Schnelligkeit", "correct": false, "because": "Funktion zählt"}, {"text": "Zufälligkeit", "correct": false, "because": "Struktur nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) DHCP vergibt IPv4-Adressen. b) Es benötigt keine Server.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) Server nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet DHCP?', 5, '[{"text": "Automatisierung", "correct": true, "because": "Vereinfacht Verwaltung"}, {"text": "Konfliktvermeidung", "correct": true, "because": "Zentrale Vergabe"}, {"text": "Datenverschlüsselung", "correct": false, "because": "Nicht DHCP"}, {"text": "Bandbreitensteigerung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei DHCP unwichtig?', 3, '[{"text": "Lease-Zeit", "correct": false, "because": "Bestimmt Gültigkeit"}, {"text": "IP-Pool", "correct": false, "because": "Definiert Adressen"}, {"text": "Schriftgröße", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann DHCP die Broadcastadresse vergeben?', 3, '[{"text": "Nein", "correct": true, "because": "Reserviert für Broadcast"}, {"text": "Ja", "correct": false, "because": "Falsche Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob DHCP mit einem Pool von 192.168.1.100-150 arbeitet?', 2, '[{"text": "Ja", "correct": true, "because": "Konfigurierbarer Bereich"}, {"text": "Nein", "correct": false, "because": "Mögliche Einstellung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Adresse wird DHCP bei 10.0.0.0/24 nicht vergeben?', 4, '[{"text": "10.0.0.255", "correct": true, "because": "Broadcastadresse"}, {"text": "10.0.0.1", "correct": false, "because": "Nutzbar"}, {"text": "10.0.0.100", "correct": false, "because": "Nutzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt der DHCP-Server?', 3, '[{"text": "Adressen verwalten", "correct": true, "because": "Zentrale Vergabe"}, {"text": "Daten routen", "correct": false, "because": "Router-Aufgabe"}, {"text": "Firewall schützen", "correct": false, "because": "Nicht DHCP"}]');
